css:
/* A. 幅を切る + 片側だけ丸める */
.band{background:#d1e0d9; width:82%; margin-left:0;
  border-radius:0 64px 64px 0; padding:56px 0 40px}
.band + section{border-top-left-radius:64px; margin-top:-24px}

/* B. 角1箇所だけ・上下で左右反転 */
.sec-orange{background:#e8763a; border-radius:0 0 0 56px}
.sec-dark  {background:#2e2f2a}
.sec-cream {background:#faf9f7; border-radius:0 56px 0 0; margin-top:-1px}
